rules.implementation:
var = str(value["SequenceVariant"].iloc[0])
if "SP" not in var:
    raise ValidationWarning(f"RF-spoiled (SequenceVariant 'SP') recommended for QSM phase. Found {var}.")

n = value["EchoTime"].dropna().nunique()
if n < 6:
    raise ValidationError(f"Only {n} echoes; HC-ChiSep needs >=8 to sample the orientation/MWF beat.")
if n < 8:
    raise ValidationWarning(f"Found {n} echoes; >=8 (ideally 10-12) recommended — 4-echo data saturated the fibre-angle estimate.")

te1 = value["EchoTime"].dropna().min()
if te1 > 8:
    raise ValidationError(f"First TE too long ({te1} ms); aim for ~3 ms.")
if te1 > 5:
    raise ValidationWarning(f"First TE could be shorter ({te1} ms); ~3 ms preferred.")

te = value["EchoTime"].dropna().sort_values()
dte = te.diff().iloc[1:].mean()
if dte > 6:
    raise ValidationError(f"Mean dTE {dte:.1f} ms too long to sample the myelin beat; aim <=4 ms.")
if dte > 4:
    raise ValidationWarning(f"Mean dTE {dte:.1f} ms; <=4 ms preferred for the beat.")

mags, phases = [], []
for et, g in value.groupby("EchoTime"):
    it = g["ImageType"]
    mags.append(sum('M' in x for x in it))
    phases.append(sum('P' in x for x in it))
if not all(m >= 1 for m in mags):
    raise ValidationError(f"Each echo needs a magnitude image. Found {mags}.")
if not all(p >= 1 for p in phases):
    raise ValidationError(f"Each echo needs a phase image. Found {phases}.")

ps = value["PixelSpacing"].iloc[0]
st = value["SliceThickness"].iloc[0]
if abs(ps[0]-ps[1]) > 0.1 or abs(ps[0]-st) > 0.1:
    raise ValidationError(f"Voxels not isotropic. PixelSpacing {ps}, SliceThickness {st}.")
if max(ps[0], ps[1], st) > 1.05:
    raise ValidationWarning(f"Voxel edge {max(ps[0],ps[1],st)} mm > 1 mm; <=1 mm preferred.")

n = value["EchoTime"].dropna().nunique()
if n < 6:
    raise ValidationError(f"Only {n} echoes; need >=8 for R2 fitting (>=32 for MWF).")
if n < 32:
    raise ValidationWarning(f"Found {n} echoes; >=32 recommended so MESE doubles as an MWF myelin reference. (>=8 is enough for R2' only.)")

b = value["DiffusionBValue"].dropna().astype(float)
if len(b) == 0:
    raise ValidationError("No DiffusionBValue found — is this a diffusion series?")
has_b0 = (b < 50).any()
shell = b[b >= 50]
if not has_b0:
    raise ValidationWarning("No b=0 volume found; needed as tensor baseline and for distortion correction.")
if len(shell) == 0 or shell.max() < 700 or shell.min() > 1300:
    raise ValidationError(f"Expected a shell near b=1000. Found b-values up to {b.max():.0f}.")

if "DiffusionGradientOrientation" not in value.columns:
    raise ValidationWarning("Cannot count directions (DiffusionGradientOrientation absent); ensure >=30 (ideally 60).")
b = value["DiffusionBValue"].fillna(0).astype(float)
dirs = set()
for ok, o in zip(b > 50, value["DiffusionGradientOrientation"]):
    if ok and o is not None and o == o:
        try:
            dirs.add(tuple(round(float(x), 3) for x in o))
        except TypeError:
            pass
n = len(dirs)
if n < 12:
    raise ValidationError(f"Only {n} diffusion directions; >=30 needed for a robust tensor (60 ideal).")
if n < 30:
    raise ValidationWarning(f"{n} directions; >=30 recommended (60 ideal) for reliable V1 -> fibre angle.")

ti = value["InversionTime"].dropna()
if len(ti) == 0 or float(ti.iloc[0]) <= 0:
    raise ValidationWarning("No InversionTime — an IR-prepared T1w (MPRAGE/BRAVO) is recommended for segmentation.")

ps = value["PixelSpacing"].iloc[0]
st = value["SliceThickness"].iloc[0]
if abs(ps[0]-ps[1]) > 0.1 or abs(ps[0]-st) > 0.15:
    raise ValidationError(f"Voxels not isotropic. PixelSpacing {ps}, SliceThickness {st}.")
if max(ps[0], ps[1], st) > 1.2:
    raise ValidationWarning(f"Voxel edge {max(ps[0],ps[1],st)} mm > ~1 mm.")
